class Account:
    interest_rate = 0.02                  # class attribute, shared

    def __init__(self, owner, balance=0):
        self.owner = owner                # instance attributes
        self._balance = balance

    def deposit(self, amount):
        if amount <= 0:
            raise ValueError("deposit must be positive")
        self._balance += amount

    @classmethod
    def from_string(cls, text):           # another way to create an Account
        owner, balance = text.split(":")
        return cls(owner, int(balance))

    def __repr__(self):
        return f"Account({self.owner!r}, {self._balance})"
acct = Account("ana", 100)
acct.deposit(50)
print(acct)                               # Account('ana', 150)
print(Account.from_string("ben:20"))      # Account('ben', 20)
print(acct.interest_rate)                 # 0.02

from abc import ABC, abstractmethod
class Shape(ABC):
    def __init__(self, name):
        self.name = name

    @abstractmethod
    def area(self): ...
    def describe(self):
        return f"{self.name} with area {self.area():.1f}"
class Rectangle(Shape):
    def __init__(self, w, h):
        super().__init__("rectangle")
        self.w, self.h = w, h
    def area(self):
        return self.w * self.h
class Square(Rectangle):
    def __init__(self, side):
        super().__init__(side, side)
        self.name = "square"
sq = Square(3)
print(sq.describe())                 # square with area 9.0
print(isinstance(sq, Shape))         # True
print([c.__name__ for c in Square.__mro__])
# ['Square', 'Rectangle', 'Shape', 'ABC', 'object']
# Shape("x") -> TypeError: can't instantiate abstract class

class AppError(Exception):
    "Base class for this application's errors."

class ConfigError(AppError):
    pass

def load_port(settings):
    try:
        port = int(settings["port"])
    except KeyError:
        raise ConfigError("missing 'port'") from None
    except ValueError as err:
        raise ConfigError(f"bad port {settings['port']!r}") from err
    else:
        return port
    finally:
        print("checked", settings)

for s in [{"port": "8080"}, {}, {"port": "eighty"}]:
    try:
        print(load_port(s))
    except AppError as e:
        print(type(e).__name__, e, "| cause:", repr(e.__cause__))

from dataclasses import dataclass, field, asdict, replace

@dataclass(frozen=True, order=True)
class Version:
    major: int
    minor: int = 0

@dataclass
class Order:
    id: int
    items: list[str] = field(default_factory=list)
    total: float = 0.0

    def __post_init__(self):
        if self.total < 0:
            raise ValueError("total must be >= 0")

o = Order(1, ["tea"], 3.5)
print(o)                  # Order(id=1, items=['tea'], total=3.5)
print(o == Order(1, ["tea"], 3.5))   # True
print(asdict(o))          # {'id': 1, 'items': ['tea'], 'total': 3.5}

v = Version(3, 12)
print(sorted([Version(3, 13), v, Version(2)]))
print(replace(v, minor=13), {v: "supported"}[v])

