import pytest
def apply_discount(price, percent):
    if not 0 <= percent <= 100:
        raise ValueError("percent must be between 0 and 100")
    return round(price * (1 - percent / 100), 2)

def test_basic_discount():
    assert apply_discount(100, 25) == 75
@pytest.mark.parametrize("price, percent, expected", [
    (10, 0, 10), (10, 100, 0), (19.99, 10, 17.99),
])
def test_edges(price, percent, expected):
    assert apply_discount(price, percent) == pytest.approx(expected)
def test_rejects_bad_percent():
    with pytest.raises(ValueError, match="between 0 and 100"):
        apply_discount(10, 150)

