import functools
def retry(times=3, exceptions=(Exception,)):
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            for attempt in range(1, times + 1):
                try:
                    return func(*args, **kwargs)
                except exceptions as e:
                    print(f"attempt {attempt} failed: {e}")
            raise RuntimeError(f"{func.__name__} failed {times} times")
        return wrapper
    return decorator

outcomes = iter([ValueError("flaky"), ValueError("flaky"), "ok"])
@retry(times=3, exceptions=(ValueError,))
def fetch():
    """Fetch something unreliable."""
    result = next(outcomes)
    if isinstance(result, Exception):
        raise result
    return result

print(fetch())                       # two failures, then: ok
print(fetch.__name__, fetch.__doc__) # fetch Fetch something unreliable.

class Money:
    def __init__(self, cents, currency="EUR"):
        self.cents, self.currency = cents, currency
    def __repr__(self):
        return f"Money({self.cents}, {self.currency!r})"
    def __eq__(self, other):
        if not isinstance(other, Money):
            return NotImplemented
        return (self.cents, self.currency) == (other.cents, other.currency)
    def __hash__(self):                   # equal objects -> equal hashes
        return hash((self.cents, self.currency))
    def __add__(self, other):
        if not isinstance(other, Money) or other.currency != self.currency:
            return NotImplemented         # let Python try other.__radd__
        return Money(self.cents + other.cents, self.currency)
    def __radd__(self, other):            # lets sum() start from 0
        return self if other == 0 else NotImplemented

wallet = [Money(250), Money(100), Money(75)]
