class Positive:                            # a reusable data descriptor
    def __set_name__(self, owner, name):
        self.private = "_" + name
    def __get__(self, obj, objtype=None):
        if obj is None: return self        # accessed on the class
        return getattr(obj, self.private)
    def __set__(self, obj, value):
        if value <= 0:
            raise ValueError(f"{self.private[1:]} must be > 0")
        setattr(obj, self.private, value)

class Product:
    price, weight = Positive(), Positive()
    def __init__(self, price, weight):
        self.price, self.weight = price, weight   # goes through __set__
    @property
    def price_per_kg(self):                # read-only computed attribute
        return round(self.price / self.weight, 2)

p = Product(12.0, 0.5)
print(p.price_per_kg)                      # 24.0
try:
    p.weight = -1
except ValueError as e:
    print(e)                               # weight must be > 0

from itertools import groupby

def read_lines(chunks):
    for chunk in chunks:
        yield from chunk.splitlines()      # delegate to another iterable

def parse(lines):
    for line in lines:
        user, amount = line.split(",")
        yield user, int(amount)
chunks = ["ana,5\nben,3", "ana,7\ncy,1"]
records = sorted(parse(read_lines(chunks)))      # lazy until sorted() pulls
for user, rows in groupby(records, key=lambda r: r[0]):
    print(user, sum(amount for _, amount in rows))   # ana 12 / ben 3 / cy 1

def averager():
    total, count, avg = 0, 0, None
    while True:
        value = yield avg                  # receives what send() passes
        total, count = total + value, count + 1
        avg = total / count

avg = averager()
next(avg)                                  # prime: run to the first yield
print(avg.send(10), avg.send(20))          # 10.0 15.0

from collections.abc import Sequence
from typing import Protocol, TypedDict, Literal, TypeIs

def first[T](items: Sequence[T]) -> T:          # generic function (3.12+)
    return items[0]

class SupportsArea(Protocol):
    def area(self) -> float: ...
class Square:                                   # no inheritance needed
    def __init__(self, s: float) -> None: self.s = s
    def area(self) -> float: return self.s ** 2

def total_area(shapes: Sequence[SupportsArea]) -> float:
    return sum(s.area() for s in shapes)

class User(TypedDict):
    name: str
    role: Literal["admin", "member"]

def is_str_list(val: list[object]) -> TypeIs[list[str]]:   # 3.13
    return all(isinstance(x, str) for x in val)

type Pair[T] = tuple[T, T]                      # generic type alias
print(first("abc"), total_area([Square(2), Square(3)]), is_str_list(["a"]))  # a 13 True
print(User(name="ana", role="admin"), Pair[int])  # a plain dict; Pair[int]

class Exporter:
    registry: dict[str, type] = {}
    def __init_subclass__(cls, *, ext: str, **kwargs):
        super().__init_subclass__(**kwargs)
        cls.ext = ext
        Exporter.registry[ext] = cls

class CsvExporter(Exporter, ext="csv"): pass
class JsonExporter(Exporter, ext="json"): pass
print(sorted(Exporter.registry))   # ['csv', 'json']

class Singleton(type):              # a metaclass: controls instance creation
    _instances = {}
    def __call__(cls, *args, **kwargs):
        if cls not in cls._instances:
            cls._instances[cls] = super().__call__(*args, **kwargs)
        return cls._instances[cls]
class Config(metaclass=Singleton):
    def __init__(self):
        print("loading config once")

print(Config() is Config())         # loading config once / True
print(type(Config).__name__, type(type).__name__)   # Singleton type
